INSERT INTO __psipedia_adoption_staging_source_0038 (name, slug, status, sex, birth_date, approximate_age_months, size, weight, breed_name, use_legacy_breed, breed_mix, region, district, city, organization_import_key, expected_organization_name, expected_organization_slug, main_image, short_description, description, use_legacy_description, external_source_url, contact_email, contact_phone, contact_url, search_text, last_verified_at) VALUES
  ('Falco', 'falco-hlada-novy-domov', 'DRAFT', 'MALE', NULL, 136, 'MEDIUM', 15.9, 'kríženec', 0, 1, 'Košický kraj', '', 'Košice', 'help-org:pomoc-unia-vzajomnej-pomoci-ludi-a-psov-u-v-p', 'Únia vzájomnej pomoci ľudí a psov (Ú.V.P.)', 'pomoc-unia-vzajomnej-pomoci-ludi-a-psov-u-v-p', NULL, 'Pokojný starší psík, ktorý má rád ľudí a ocení primerané prechádzky aj blízkosť rodiny.', 'Falco je kríženec narodený približne v máji 2015. Podľa útulku je pokojný, priateľský k ľuďom a pri primeranom režime sa dobre správa aj v interiéri. So psami vie fungovať, viac mu vyhovujú pokojné a nevtieravé povahy. Hľadá byt alebo dom s prístupom dovnútra a zodpovednú rodinu, ktorá mu dopraje bezpečie a pravidelný pohyb.', 0, 'https://www.uvp.sk/zvierata-na-osvojenie/falco/', NULL, '0907 441 447', 'https://www.uvp.sk/zvierata-na-osvojenie/falco/', 'falco krizenec kosicky kraj kosice unia vzajomnej pomoci ludi a psov u v p pokojny starsi psik ktory ma rad ludi a oceni primerane prechadzky aj blizkost rodiny', '2026-09-13T00:00:00.000Z'),
  ('Lana', 'lana-hlada-novy-domov', 'DRAFT', 'FEMALE', NULL, 13, 'MEDIUM', 13.5, 'kríženec (útulok predpokladá podiel border kólie)', 0, 1, 'Košický kraj', '', 'Košice', 'help-org:pomoc-unia-vzajomnej-pomoci-ludi-a-psov-u-v-p', 'Únia vzájomnej pomoci ľudí a psov (Ú.V.P.)', 'pomoc-unia-vzajomnej-pomoci-ludi-a-psov-u-v-p', NULL, 'Mladá aktívna fenka s chuťou spolupracovať, vhodná pre ľudí, ktorí jej dajú pohyb aj mentálne zamestnanie.', 'Lana je mladá kríženka narodená približne v auguste 2025. Útulok ju opisuje ako vnímavú, aktívnu a učenlivú; predpokladá aj podiel border kólie. Potrebuje pravidelný fyzický pohyb, mentálne zamestnanie a kontakt s človekom. Vhodné je bývanie v byte alebo dome s plnohodnotným prístupom dovnútra.', 0, 'https://www.uvp.sk/zvierata-na-osvojenie/lana/', NULL, '0907 441 447', 'https://www.uvp.sk/zvierata-na-osvojenie/lana/', 'lana krizenec utulok predpoklada podiel border kolie kosicky kraj kosice unia vzajomnej pomoci ludi a psov u v p mlada aktivna fenka s chutou spolupracovat vhodna pre ludi ktori jej daju pohyb aj mentalne zamestnanie', '2026-09-13T00:00:00.000Z'),
  ('Joly', 'joly-hlada-novy-domov', 'DRAFT', 'FEMALE', NULL, 19, 'MEDIUM', 17.9, 'kríženec', 0, 1, 'Košický kraj', '', 'Košice', 'help-org:pomoc-unia-vzajomnej-pomoci-ludi-a-psov-u-v-p', 'Únia vzájomnej pomoci ľudí a psov (Ú.V.P.)', 'pomoc-unia-vzajomnej-pomoci-ludi-a-psov-u-v-p', NULL, 'Jemná, priateľská a aktívna fenka, ktorá po úvodnom strese pekne napreduje a rada spolupracuje s človekom.', 'Joly je kríženka narodená približne vo februári 2025. Po príchode bola vystresovaná, bez agresívnych prejavov; podľa útulku je dnes priateľská, hravá a aktívna. Vychádza so psami a pri pravidelnom venčení má dobré hygienické návyky, pri nude však môže ničiť veci. Hľadá aktívnejšiu domácnosť v byte alebo dome s prístupom dovnútra.', 0, 'https://www.uvp.sk/zvierata-na-osvojenie/joly/', NULL, '0907 441 447', 'https://www.uvp.sk/zvierata-na-osvojenie/joly/', 'joly krizenec kosicky kraj kosice unia vzajomnej pomoci ludi a psov u v p jemna priatelska a aktivna fenka ktora po uvodnom strese pekne napreduje a rada spolupracuje s clovekom', '2026-09-13T00:00:00.000Z'),
  ('Clinton', 'clinton-hlada-novy-domov', 'DRAFT', 'MALE', NULL, 32, 'LARGE', 52, 'kríženec', 0, 1, 'Košický kraj', '', 'Košice', 'help-org:pomoc-unia-vzajomnej-pomoci-ludi-a-psov-u-v-p', 'Únia vzájomnej pomoci ľudí a psov (Ú.V.P.)', 'pomoc-unia-vzajomnej-pomoci-ludi-a-psov-u-v-p', NULL, 'Veľký a silný, pritom hravý pes, ktorý potrebuje skúseného a zodpovedného človeka.', 'Clinton je kríženec narodený približne v januári 2024. Je veľmi veľký a fyzicky silný, podľa útulku však hravý a ľudí má rád. Potrebuje skúseného majiteľa, ktorý zvládne jeho silu, nastaví jasné pravidlá a poskytne mu dostatok priestoru aj kontaktu s rodinou. Odporúčaný je dom s plnohodnotným prístupom dovnútra.', 0, 'https://www.uvp.sk/zvierata-na-osvojenie/clinton/', 'alexandra.slobodnikova@gmail.com', '0905 671 142', 'https://www.uvp.sk/zvierata-na-osvojenie/clinton/', 'clinton krizenec kosicky kraj kosice unia vzajomnej pomoci ludi a psov u v p velky a silny pritom hravy pes ktory potrebuje skuseneho a zodpovedneho cloveka', '2026-09-13T00:00:00.000Z'),
  ('Bado', 'bado-hlada-novy-domov', 'DRAFT', 'MALE', NULL, 78, 'SMALL', 8.7, 'kríženec', 0, 1, 'Košický kraj', '', 'Košice', 'help-org:pomoc-unia-vzajomnej-pomoci-ludi-a-psov-u-v-p', 'Únia vzájomnej pomoci ľudí a psov (Ú.V.P.)', 'pomoc-unia-vzajomnej-pomoci-ludi-a-psov-u-v-p', NULL, 'Pokojný a priateľský malý psík, ktorý je slepý a potrebuje bezpečné prostredie a citlivé vedenie.', 'Bado je kríženec narodený približne v marci 2020. Je slepý na obe oči v dôsledku obojstranného poškodenia sietnice, no podľa útulku sa pri človeku orientuje dobre a na vodítku ho vie nasledovať. Je pokojný, priateľský, vychádza so psami a pri prechádzkach zvládal aj kontakt s deťmi. Potrebuje bezpečnú domácnosť bez rizikových prekážok a človeka, ktorý ho bude spoľahlivo viesť.', 0, 'https://www.uvp.sk/zvierata-na-osvojenie/bado/', NULL, '0907 441 447', 'https://www.uvp.sk/zvierata-na-osvojenie/bado/', 'bado krizenec kosicky kraj kosice unia vzajomnej pomoci ludi a psov u v p pokojny a priatelsky maly psik ktory je slepy a potrebuje bezpecne prostredie a citlive vedenie', '2026-09-13T00:00:00.000Z'),
  ('Ruth', 'ruth-hlada-novy-domov', 'DRAFT', 'FEMALE', NULL, 7, 'MEDIUM', 14.2, 'kríženec', 0, 1, 'Košický kraj', '', 'Košice', 'help-org:pomoc-unia-vzajomnej-pomoci-ludi-a-psov-u-v-p', 'Únia vzájomnej pomoci ľudí a psov (Ú.V.P.)', 'pomoc-unia-vzajomnej-pomoci-ludi-a-psov-u-v-p', NULL, 'Veselá mladá fenka s množstvom energie, ktorá má rada ľudí aj psov a potrebuje aktívny domov.', 'Ruth je kríženka narodená približne vo februári 2026. Útulok ju opisuje ako mladú, energickú, veselú a priateľskú k ľuďom aj psom. Hygienické návyky ešte potrebuje doladiť. Hľadá aktívnu rodinu, ktorá jej poskytne pohyb, výchovu a bývanie v byte alebo dome s plným prístupom dovnútra.', 0, 'https://www.uvp.sk/zvierata-na-osvojenie/ruth/', NULL, '0907 441 447', 'https://www.uvp.sk/zvierata-na-osvojenie/ruth/', 'ruth krizenec kosicky kraj kosice unia vzajomnej pomoci ludi a psov u v p vesela mlada fenka s mnozstvom energie ktora ma rada ludi aj psov a potrebuje aktivny domov', '2026-09-13T00:00:00.000Z'),
  ('Rosie', 'rosie-hlada-novy-domov', 'DRAFT', 'FEMALE', NULL, 3, 'MEDIUM', NULL, 'kríženec', 0, 1, 'Košický kraj', '', 'Košice', 'help-org:pomoc-unia-vzajomnej-pomoci-ludi-a-psov-u-v-p', 'Únia vzájomnej pomoci ľudí a psov (Ú.V.P.)', 'pomoc-unia-vzajomnej-pomoci-ludi-a-psov-u-v-p', NULL, 'Priateľské a hravé šteniatko, ktoré sa ešte učí hygienu, režim a základy života v rodine.', 'Rosie je kríženka narodená približne v júni 2026. Je priateľská, hravá, aktívna a dobre motivovateľná k učeniu. Ako šteňa potrebuje pravidelný režim, socializáciu, trpezlivosť a dokončenie hygienických návykov. Útulok odhaduje hmotnosť v dospelosti približne na 20 kg; vhodný je byt alebo dom s prístupom dovnútra.', 0, 'https://www.uvp.sk/zvierata-na-osvojenie/rosie/', NULL, '0907 441 447', 'https://www.uvp.sk/zvierata-na-osvojenie/rosie/', 'rosie krizenec kosicky kraj kosice unia vzajomnej pomoci ludi a psov u v p priatelske a hrave steniatko ktore sa este uci hygienu rezim a zaklady zivota v rodine', '2026-09-13T00:00:00.000Z'),
  ('Ruby', 'ruby-hlada-novy-domov', 'DRAFT', 'FEMALE', NULL, 3, 'MEDIUM', NULL, 'kríženec', 0, 1, 'Košický kraj', '', 'Košice', 'help-org:pomoc-unia-vzajomnej-pomoci-ludi-a-psov-u-v-p', 'Únia vzájomnej pomoci ľudí a psov (Ú.V.P.)', 'pomoc-unia-vzajomnej-pomoci-ludi-a-psov-u-v-p', NULL, 'Aktívne a učenlivé šteniatko, ktoré hľadá rodinu pripravenú na dôslednú socializáciu a výchovu.', 'Ruby je kríženka narodená približne v júni 2026. Podľa útulku je priateľská, hravá, aktívna a dobre sa učí. Potrebuje pravidelný režim, socializáciu, trpezlivosť a dokončenie hygienických návykov. Útulok odhaduje dospelú hmotnosť približne na 20 kg; bývanie má byť v byte alebo dome s prístupom dovnútra.', 0, 'https://www.uvp.sk/zvierata-na-osvojenie/ruby/', NULL, '0907 441 447', 'https://www.uvp.sk/zvierata-na-osvojenie/ruby/', 'ruby krizenec kosicky kraj kosice unia vzajomnej pomoci ludi a psov u v p aktivne a ucenlive steniatko ktore hlada rodinu pripravenu na doslednu socializaciu a vychovu', '2026-09-13T00:00:00.000Z'),
  ('Asta', 'asta-hlada-novy-domov', 'DRAFT', 'FEMALE', NULL, 4, 'MEDIUM', NULL, 'kríženec', 0, 1, 'Košický kraj', '', 'Košice', 'help-org:pomoc-unia-vzajomnej-pomoci-ludi-a-psov-u-v-p', 'Únia vzájomnej pomoci ľudí a psov (Ú.V.P.)', 'pomoc-unia-vzajomnej-pomoci-ludi-a-psov-u-v-p', NULL, 'Veselé mladé šteňa, ktoré potrebuje čas, pohyb, socializáciu a láskavo nastavené pravidlá.', 'Asta je kríženka narodená približne v máji 2026. Je priateľská, hravá a aktívna, s potenciálom dobre sa učiť. Ako mladý pes potrebuje dôslednú socializáciu, pravidelný režim a doladenie hygienických návykov. Útulok odhaduje dospelú hmotnosť približne na 25 kg a odporúča bývanie s plným prístupom dovnútra.', 0, 'https://www.uvp.sk/zvierata-na-osvojenie/asta/', NULL, '0907 441 447', 'https://www.uvp.sk/zvierata-na-osvojenie/asta/', 'asta krizenec kosicky kraj kosice unia vzajomnej pomoci ludi a psov u v p vesele mlade stena ktore potrebuje cas pohyb socializaciu a laskavo nastavene pravidla', '2026-09-13T00:00:00.000Z'),
  ('Lionel', 'lionel-hlada-novy-domov', 'DRAFT', 'MALE', '2026-06-29', NULL, 'MEDIUM', NULL, 'kríženec', 0, 1, 'Košický kraj', '', 'Košice', 'help-org:pomoc-unia-vzajomnej-pomoci-ludi-a-psov-u-v-p', 'Únia vzájomnej pomoci ľudí a psov (Ú.V.P.)', 'pomoc-unia-vzajomnej-pomoci-ludi-a-psov-u-v-p', NULL, 'Hravé šteniatko z vrhu fenky Luny, pripravené učiť sa životu v rodine.', 'Lionel sa narodil 29. júna 2026 ako jedno zo šiestich šteniat fenky Luny. Je priateľský, hravý a aktívny; potrebuje socializáciu, pravidelný režim, trpezlivé učenie a dokončenie hygienických návykov. Útulok odhaduje dospelú hmotnosť približne na 20 kg. Vhodné je bývanie v byte alebo dome s prístupom dovnútra.', 0, 'https://www.uvp.sk/zvierata-na-osvojenie/lionel/', NULL, '0907 441 447', 'https://www.uvp.sk/zvierata-na-osvojenie/lionel/', 'lionel krizenec kosicky kraj kosice unia vzajomnej pomoci ludi a psov u v p hrave steniatko z vrhu fenky luny pripravene ucit sa zivotu v rodine', '2026-09-13T00:00:00.000Z'),
  ('Leony', 'leony-hlada-novy-domov', 'DRAFT', 'FEMALE', '2026-06-29', NULL, 'MEDIUM', NULL, 'kríženec', 0, 1, 'Košický kraj', '', 'Košice', 'help-org:pomoc-unia-vzajomnej-pomoci-ludi-a-psov-u-v-p', 'Únia vzájomnej pomoci ľudí a psov (Ú.V.P.)', 'pomoc-unia-vzajomnej-pomoci-ludi-a-psov-u-v-p', NULL, 'Mladá hravá fenka z vrhu Luny, ktorá potrebuje rodinu pripravenú na poctivú výchovu šteniatka.', 'Leony sa narodila 29. júna 2026 ako jedno zo šiestich šteniat fenky Luny. Je priateľská, hravá a aktívna a potrebuje socializáciu, režim, trpezlivé učenie a dokončenie hygienických návykov. Útulok odhaduje dospelú hmotnosť približne na 20 kg. Vhodné je bývanie v byte alebo dome s prístupom dovnútra.', 0, 'https://www.uvp.sk/zvierata-na-osvojenie/leony/', NULL, '0907 441 447', 'https://www.uvp.sk/zvierata-na-osvojenie/leony/', 'leony krizenec kosicky kraj kosice unia vzajomnej pomoci ludi a psov u v p mlada hrava fenka z vrhu luny ktora potrebuje rodinu pripravenu na poctivu vychovu steniatka', '2026-09-13T00:00:00.000Z'),
  ('Lorie', 'lorie-hlada-novy-domov', 'DRAFT', 'FEMALE', '2026-06-29', NULL, 'MEDIUM', NULL, 'kríženec', 0, 1, 'Košický kraj', '', 'Košice', 'help-org:pomoc-unia-vzajomnej-pomoci-ludi-a-psov-u-v-p', 'Únia vzájomnej pomoci ľudí a psov (Ú.V.P.)', 'pomoc-unia-vzajomnej-pomoci-ludi-a-psov-u-v-p', NULL, 'Priateľské a aktívne šteniatko z vrhu Luny, ktoré si hľadá zodpovedný domov.', 'Lorie sa narodila 29. júna 2026 ako jedno zo šiestich šteniat fenky Luny. Potrebuje bežnú šteniatkovskú socializáciu, pravidelný režim, trpezlivé učenie a dokončenie hygienických návykov. Útulok odhaduje dospelú hmotnosť približne na 20 kg. Hľadá byt alebo dom s prístupom dovnútra a rodinu pripravenú venovať sa jej dlhodobo.', 0, 'https://www.uvp.sk/zvierata-na-osvojenie/lorie/', NULL, '0907 441 447', 'https://www.uvp.sk/zvierata-na-osvojenie/lorie/', 'lorie krizenec kosicky kraj kosice unia vzajomnej pomoci ludi a psov u v p priatelske a aktivne steniatko z vrhu luny ktore si hlada zodpovedny domov', '2026-09-13T00:00:00.000Z'),
  ('Lety', 'lety-hlada-novy-domov', 'DRAFT', 'FEMALE', '2026-06-29', NULL, 'MEDIUM', NULL, 'kríženec', 0, 1, 'Košický kraj', '', 'Košice', 'help-org:pomoc-unia-vzajomnej-pomoci-ludi-a-psov-u-v-p', 'Únia vzájomnej pomoci ľudí a psov (Ú.V.P.)', 'pomoc-unia-vzajomnej-pomoci-ludi-a-psov-u-v-p', NULL, 'Veselé šteniatko z vrhu Luny, vhodné pre rodinu, ktorá zvládne obdobie socializácie a učenia.', 'Lety sa narodila 29. júna 2026 ako jedno zo šiestich šteniat fenky Luny. Je mladá, hravá a aktívna; potrebuje pravidelný režim, socializáciu, trpezlivé učenie a doladenie hygienických návykov. Útulok odhaduje dospelú hmotnosť približne na 20 kg. Hľadá domácnosť s plnohodnotným prístupom dovnútra.', 0, 'https://www.uvp.sk/zvierata-na-osvojenie/lety/', NULL, '0907 441 447', 'https://www.uvp.sk/zvierata-na-osvojenie/lety/', 'lety krizenec kosicky kraj kosice unia vzajomnej pomoci ludi a psov u v p vesele steniatko z vrhu luny vhodne pre rodinu ktora zvladne obdobie socializacie a ucenia', '2026-09-13T00:00:00.000Z'),
  ('Laron', 'laron-hlada-novy-domov', 'DRAFT', 'MALE', '2026-06-29', NULL, 'MEDIUM', NULL, 'kríženec', 0, 1, 'Košický kraj', '', 'Košice', 'help-org:pomoc-unia-vzajomnej-pomoci-ludi-a-psov-u-v-p', 'Únia vzájomnej pomoci ľudí a psov (Ú.V.P.)', 'pomoc-unia-vzajomnej-pomoci-ludi-a-psov-u-v-p', NULL, 'Mladý psík z vrhu Luny, ktorý potrebuje zodpovednú socializáciu a trpezlivú výchovu.', 'Laron sa narodil 29. júna 2026 ako jedno zo šiestich šteniat fenky Luny. Je hravý a aktívny, potrebuje pravidelný režim, socializáciu, trpezlivé učenie a dokončenie hygienických návykov. Útulok odhaduje dospelú hmotnosť približne na 20 kg. Vhodný je byt alebo dom s prístupom dovnútra.', 0, 'https://www.uvp.sk/zvierata-na-osvojenie/laron/', NULL, '0907 441 447', 'https://www.uvp.sk/zvierata-na-osvojenie/laron/', 'laron krizenec kosicky kraj kosice unia vzajomnej pomoci ludi a psov u v p mlady psik z vrhu luny ktory potrebuje zodpovednu socializaciu a trpezlivu vychovu', '2026-09-13T00:00:00.000Z'),
  ('Lussy', 'lussy-hlada-novy-domov', 'DRAFT', 'FEMALE', '2026-06-29', NULL, 'MEDIUM', NULL, 'kríženec', 0, 1, 'Košický kraj', '', 'Košice', 'help-org:pomoc-unia-vzajomnej-pomoci-ludi-a-psov-u-v-p', 'Únia vzájomnej pomoci ľudí a psov (Ú.V.P.)', 'pomoc-unia-vzajomnej-pomoci-ludi-a-psov-u-v-p', NULL, 'Priateľské šteniatko z vrhu Luny, ktoré čaká na rodinu pripravenú venovať sa jeho vývoju.', 'Lussy sa narodila 29. júna 2026 ako jedno zo šiestich šteniat fenky Luny. Ako mladá fenka potrebuje socializáciu, pravidelný režim, trpezlivé učenie a dokončenie hygienických návykov. Útulok odhaduje dospelú hmotnosť približne na 20 kg. Hľadá byt alebo dom s plnohodnotným prístupom dovnútra.', 0, 'https://www.uvp.sk/zvierata-na-osvojenie/lussy/', NULL, '0907 441 447', 'https://www.uvp.sk/zvierata-na-osvojenie/lussy/', 'lussy krizenec kosicky kraj kosice unia vzajomnej pomoci ludi a psov u v p priatelske steniatko z vrhu luny ktore caka na rodinu pripravenu venovat sa jeho vyvoju', '2026-09-13T00:00:00.000Z'),
  ('Luna', 'luna-hlada-novy-domov', 'DRAFT', 'FEMALE', NULL, 52, 'MEDIUM', 22.7, 'kríženec', 0, 1, 'Košický kraj', '', 'Košice', 'help-org:pomoc-unia-vzajomnej-pomoci-ludi-a-psov-u-v-p', 'Únia vzájomnej pomoci ľudí a psov (Ú.V.P.)', 'pomoc-unia-vzajomnej-pomoci-ludi-a-psov-u-v-p', NULL, 'Mladá aktívna fenka a mama šiestich šteniat, ktorá má rada ľudí a čaká na vlastnú rodinu.', 'Luna je kríženka narodená približne v máji 2022. Do útulku prišla vo veľmi zlom stave a krátko nato porodila šesť šteniat; dnes ju útulok opisuje ako mladú, aktívnu a energickú fenku, ktorá má rada ľudí. S psami samcami sa vie hrať, reakcia na fenky nebola podľa profilu overená. Hľadá byt alebo dom s prístupom dovnútra; pri vonkajšom bývaní by potrebovala kvalitné zázemie, pohyb a intenzívny kontakt s ľuďmi.', 0, 'https://www.uvp.sk/zvierata-na-osvojenie/luna/', NULL, '0907 441 447', 'https://www.uvp.sk/zvierata-na-osvojenie/luna/', 'luna krizenec kosicky kraj kosice unia vzajomnej pomoci ludi a psov u v p mlada aktivna fenka a mama siestich steniat ktora ma rada ludi a caka na vlastnu rodinu', '2026-09-13T00:00:00.000Z'),
  ('Nixie', 'nixie-hlada-novy-domov', 'DRAFT', 'FEMALE', NULL, 16, 'MEDIUM', 11, 'kríženec', 0, 1, 'Trnavský kraj', 'Dunajská Streda', 'Veľký Meder', 'help-org:pomoc-dog-azyl-o-z', 'DOG AZYL, o.z.', 'pomoc-dog-azyl-o-z', NULL, 'Energická a spoločenská mladá fenka, ktorá miluje ľudí aj hry s inými psami.', 'Nixie je kríženka narodená približne v máji 2025. Po ťažkom štarte do života a prekonaní parvovirózy je podľa organizácie veselá, odvážna a veľmi kontaktná; dobre chodí na vodítku a rada sa učí. S inými psami je priateľská a hravá. Hľadá aktívnu rodinu, ideálne dom s celoročným bývaním vo vnútri; byt je možný pri dostatku pohybu a doladení hygieny.', 0, 'https://www.dogazyl.sk/na-adopciu/nixie', 'info.dogazyl@gmail.com', NULL, 'https://www.dogazyl.sk/na-adopciu/nixie', 'nixie krizenec trnavsky kraj dunajska streda velky meder dog azyl o z energicka a spolocenska mlada fenka ktora miluje ludi aj hry s inymi psami', '2026-09-13T00:00:00.000Z'),
  ('Laraya', 'laraya-hlada-novy-domov', 'DRAFT', 'FEMALE', NULL, 87, 'LARGE', 43, 'cane corso', 0, 0, 'Trnavský kraj', 'Dunajská Streda', 'Veľký Meder', 'help-org:pomoc-dog-azyl-o-z', 'DOG AZYL, o.z.', 'pomoc-dog-azyl-o-z', NULL, 'Pokojná, nežná a oddaná fenka cane corso, ktorá potrebuje stabilný domov a skúsenosť s väčšími plemenami.', 'Laraya je sučka cane corso narodená približne v júni 2019. Organizácia ju opisuje ako pokojnú, rozumnú, oddanú a dobre ovládateľnú, s peknou chôdzou na vodítku. So psami vychádza, nevyhovujú jej však príliš dominantní alebo dotieraví jedinci. Hľadá rodinu so skúsenosťami s väčšími plemenami a bývanie s celoročným prístupom dovnútra.', 0, 'https://www.dogazyl.sk/na-adopciu/laraya', 'info.dogazyl@gmail.com', NULL, 'https://www.dogazyl.sk/na-adopciu/laraya', 'laraya cane corso trnavsky kraj dunajska streda velky meder dog azyl o z pokojna nezna a oddana fenka cane corso ktora potrebuje stabilny domov a skusenost s vacsimi plemenami', '2026-09-13T00:00:00.000Z'),
  ('Naya', 'naya-hlada-novy-domov', 'DRAFT', 'FEMALE', NULL, 23, 'MEDIUM', 20, 'kríženec', 0, 1, 'Trnavský kraj', 'Dunajská Streda', 'Veľký Meder', 'help-org:pomoc-dog-azyl-o-z', 'DOG AZYL, o.z.', 'pomoc-dog-azyl-o-z', NULL, 'Láskavá, dôverčivá a aktívna fenka, ktorá sa rýchlo priatelí s ľuďmi aj so psami.', 'Naya je kríženka narodená približne v októbri 2024. Je veľmi priateľská, kontaktná, inteligentná a energická, podľa organizácie bezproblémová aj v spoločnosti iných psov a dobre ovláda vodítko. Hľadá aktívnu rodinu, ktorá jej dopraje výlety, pohyb a veľa spoločného času. Ideálny je dom s celoročným prístupom k rodine.', 0, 'https://www.dogazyl.sk/na-adopciu/naya', 'info.dogazyl@gmail.com', NULL, 'https://www.dogazyl.sk/na-adopciu/naya', 'naya krizenec trnavsky kraj dunajska streda velky meder dog azyl o z laskava doverciva a aktivna fenka ktora sa rychlo priateli s ludmi aj so psami', '2026-09-13T00:00:00.000Z'),
  ('Zahir', 'zahir-hlada-novy-domov', 'DRAFT', 'MALE', NULL, 104, 'MEDIUM', 17, 'kríženec', 0, 1, 'Trnavský kraj', 'Dunajská Streda', 'Veľký Meder', 'help-org:pomoc-dog-azyl-o-z', 'DOG AZYL, o.z.', 'pomoc-dog-azyl-o-z', NULL, 'Pokorný a láskavý pes, ktorý po zanedbanej minulosti veľmi dobre reaguje na bezpečie a blízkosť človeka.', 'Zahir je kríženec narodený približne v januári 2018. Po rokoch v zlých podmienkach sa podľa organizácie rýchlo otvoril ľuďom a dnes je vďačný, pokojný a priateľský. So psami vychádza bez problémov, pekne chodí na vodítku a môže fungovať v aktívnejšej aj pokojnejšej rodine. Potrebuje byť členom domácnosti, nie psom odloženým na dvore.', 0, 'https://www.dogazyl.sk/na-adopciu/zahir', 'info.dogazyl@gmail.com', NULL, 'https://www.dogazyl.sk/na-adopciu/zahir', 'zahir krizenec trnavsky kraj dunajska streda velky meder dog azyl o z pokorny a laskavy pes ktory po zanedbanej minulosti velmi dobre reaguje na bezpecie a blizkost cloveka', '2026-09-13T00:00:00.000Z'),
  ('Winnie', 'winnie-hlada-novy-domov', 'DRAFT', 'FEMALE', NULL, 16, 'MEDIUM', 13, 'kríženec', 0, 1, 'Trnavský kraj', 'Dunajská Streda', 'Veľký Meder', 'help-org:pomoc-dog-azyl-o-z', 'DOG AZYL, o.z.', 'pomoc-dog-azyl-o-z', NULL, 'Mladá kontaktná fenka, ktorá prekonala strach z ľudí a dnes hľadá aktívnu a trpezlivú rodinu.', 'Winnie je kríženka narodená približne v máji 2025. Po nájdení bola veľmi vystrašená, no postupne získala dôveru a dnes je veselá, láskyplná a kontaktná; pri cudzích môže byť spočiatku opatrná. Má rada pohyb, nové miesta a hry s inými psami. Hľadá aktívnu domácnosť s dostatkom pohybu a trpezlivým pokračovaním v budovaní sebavedomia.', 0, 'https://www.dogazyl.sk/na-adopciu/winnie', 'info.dogazyl@gmail.com', NULL, 'https://www.dogazyl.sk/na-adopciu/winnie', 'winnie krizenec trnavsky kraj dunajska streda velky meder dog azyl o z mlada kontaktna fenka ktora prekonala strach z ludi a dnes hlada aktivnu a trpezlivu rodinu', '2026-09-13T00:00:00.000Z'),
  ('Rashid', 'rashid-hlada-novy-domov', 'DRAFT', 'MALE', NULL, 17, 'MEDIUM', 12, 'kríženec', 0, 1, 'Trnavský kraj', 'Dunajská Streda', 'Veľký Meder', 'help-org:pomoc-dog-azyl-o-z', 'DOG AZYL, o.z.', 'pomoc-dog-azyl-o-z', NULL, 'Veselý, učenlivý a veľmi spoločenský mladý pes, ktorý potrebuje aktívnu rodinu a ďalšiu socializáciu.', 'Rashid je kríženec narodený približne v apríli 2025. Je energický, kontaktný, ľudí miluje a s inými psami je nekonfliktný a hravý. Na vodítku ešte naberá istotu, no organizácia ho opisuje ako šikovného a učenlivého. Hľadá aktívnu rodinu, ktorá mu zabezpečí pohyb, nové skúsenosti a celoročné bývanie pri svojich ľuďoch.', 0, 'https://www.dogazyl.sk/na-adopciu/rashid', 'info.dogazyl@gmail.com', NULL, 'https://www.dogazyl.sk/na-adopciu/rashid', 'rashid krizenec trnavsky kraj dunajska streda velky meder dog azyl o z vesely ucenlivy a velmi spolocensky mlady pes ktory potrebuje aktivnu rodinu a dalsiu socializaciu', '2026-09-13T00:00:00.000Z'),
  ('Royal', 'royal-hlada-novy-domov', 'DRAFT', 'MALE', NULL, 85, 'MEDIUM', 18, 'kríženec', 0, 1, 'Trnavský kraj', 'Dunajská Streda', 'Veľký Meder', 'help-org:pomoc-dog-azyl-o-z', 'DOG AZYL, o.z.', 'pomoc-dog-azyl-o-z', NULL, 'Citlivý, pokojný a nekonfliktný pes, ktorý potrebuje trpezlivú rodinu a bezpečné domáce prostredie.', 'Royal je kríženec narodený približne v auguste 2019. Po živote v zlých podmienkach je podľa organizácie nežný, citlivý a pokorný; pri pokojnom prístupe rýchlo napreduje. S inými psami vychádza a vyrovnaný psí kamarát mu môže pomôcť cítiť sa istejšie. Na vodítku ešte potrebuje sebavedomie a hľadá rodinu, ktorá mu dá čas, bezpečie a celoročný prístup dovnútra.', 0, 'https://www.dogazyl.sk/na-adopciu/royal', 'info.dogazyl@gmail.com', NULL, 'https://www.dogazyl.sk/na-adopciu/royal', 'royal krizenec trnavsky kraj dunajska streda velky meder dog azyl o z citlivy pokojny a nekonfliktny pes ktory potrebuje trpezlivu rodinu a bezpecne domace prostredie', '2026-09-13T00:00:00.000Z'),
  ('Regina', 'regina-hlada-novy-domov', 'DRAFT', 'FEMALE', NULL, 24, 'MEDIUM', 23, 'kríženec', 0, 1, 'Trnavský kraj', 'Dunajská Streda', 'Veľký Meder', 'help-org:pomoc-dog-azyl-o-z', 'DOG AZYL, o.z.', 'pomoc-dog-azyl-o-z', NULL, 'Sebavedomá, veselá a veľmi aktívna fenka pre rodinu, ktorá chce športového a učenlivého parťáka.', 'Regina je kríženka narodená približne v septembri 2024. Je energická, zvedavá, kontaktná a inteligentná, dobre pracuje s človekom a pekne chodí na vodítku. So psami vychádza bez problémov a rada sa hrá. Hľadá aktívnu rodinu na prechádzky, výlety či turistiku a domov, kde bude plnohodnotným členom rodiny s celoročným prístupom dovnútra.', 0, 'https://www.dogazyl.sk/na-adopciu/regina', 'info.dogazyl@gmail.com', NULL, 'https://www.dogazyl.sk/na-adopciu/regina', 'regina krizenec trnavsky kraj dunajska streda velky meder dog azyl o z sebavedoma vesela a velmi aktivna fenka pre rodinu ktora chce sportoveho a ucenliveho partaka', '2026-09-13T00:00:00.000Z'),
  ('Didy', 'didy-hlada-novy-domov', 'DRAFT', 'FEMALE', NULL, 36, 'UNKNOWN', NULL, 'kríženec', 0, 1, 'Trnavský kraj', 'Trnava', 'Trnava', 'help-org:pomoc-zdruzenie-na-ochranu-zvierat-trnava', 'Združenie na ochranu zvierat Trnava', 'pomoc-zdruzenie-na-ochranu-zvierat-trnava', NULL, 'Veľmi milá a prítulná fenka, ktorá silno vyhľadáva ľudskú spoločnosť a potrebuje rodinu s dostatkom času.', 'Didy je približne trojročná kríženka nájdená dehydrovaná a zoslabnutá po šteniatkach. Útulok ju opisuje ako veľmi milú a prítulnú fenku, ktorá miluje ľudí a najradšej zostáva v ich blízkosti. Samotu znáša ťažšie a narieka, preto hľadá rodinu s dostatkom času a kontaktu. V profile je uvedené, že je očkovaná; sterilizácia bola plánovaná.', 0, 'https://www.trnava.utulok.sk/psy/didy', 'inga.novakova@centrum.sk', '0903 450 832', 'https://www.trnava.utulok.sk/psy/didy', 'didy krizenec trnavsky kraj trnava trnava zdruzenie na ochranu zvierat trnava velmi mila a pritulna fenka ktora silno vyhladava ludsku spolocnost a potrebuje rodinu s dostatkom casu', '2026-09-13T00:00:00.000Z'),
  ('Greg', 'greg-hlada-novy-domov', 'DRAFT', 'MALE', NULL, 84, 'LARGE', NULL, 'kríženec novofundlandského psa a huskyho', 0, 1, 'Trnavský kraj', 'Trnava', 'Trnava', 'help-org:pomoc-zdruzenie-na-ochranu-zvierat-trnava', 'Združenie na ochranu zvierat Trnava', 'pomoc-zdruzenie-na-ochranu-zvierat-trnava', NULL, 'Pokojnejší sedemročný kríženec, ktorý je silno naviazaný na svoju sestru Darmu a má veľmi dobrý vzťah k deťom.', 'Greg je sedemročný kríženec novofundlandského psa a huskyho. Do útulku prišiel so sestrou Darmou a odlúčenie aj pobyt v útulku znáša ťažko. Podľa útulku je vo dvojici poddajnejší, na svoju sestru je naviazaný a miluje deti, s ktorými vyrastal. Hľadá rodinu, na ktorú sa bude môcť znovu bezpečne naviazať.', 0, 'https://www.trnava.utulok.sk/psy/greg', 'inga.novakova@centrum.sk', '0903 450 832', 'https://www.trnava.utulok.sk/psy/greg', 'greg krizenec novofundlandskeho psa a huskyho trnavsky kraj trnava trnava zdruzenie na ochranu zvierat trnava pokojnejsi sedemrocny krizenec ktory je silno naviazany na svoju sestru darmu a ma velmi dobry vztah k detom', '2026-09-13T00:00:00.000Z'),
  ('Darma', 'darma-hlada-novy-domov', 'DRAFT', 'FEMALE', NULL, 84, 'LARGE', NULL, 'kríženec huskyho a novofundlandského psa', 0, 1, 'Trnavský kraj', 'Trnava', 'Trnava', 'help-org:pomoc-zdruzenie-na-ochranu-zvierat-trnava', 'Združenie na ochranu zvierat Trnava', 'pomoc-zdruzenie-na-ochranu-zvierat-trnava', NULL, 'Priateľská sedemročná fenka zvyknutá na rodinný život a deti, ktorá potrebuje návrat do stabilného domáceho prostredia.', 'Darma je sedemročná kríženka huskyho a novofundlandského psa. Vyrastala v rodine spolu s bratom Gregom a útulok uvádza, že deti má rada a k ľuďom je priateľská. Je sebavedomejšia z dvojice a útulkové prostredie jej nevyhovuje. Hľadá stabilnú rodinu, ktorá jej vráti istotu a každodenný kontakt s ľuďmi.', 0, 'https://www.trnava.utulok.sk/psy/darma', 'inga.novakova@centrum.sk', '0903 450 832', 'https://www.trnava.utulok.sk/psy/darma', 'darma krizenec huskyho a novofundlandskeho psa trnavsky kraj trnava trnava zdruzenie na ochranu zvierat trnava priatelska sedemrocna fenka zvyknuta na rodinny zivot a deti ktora potrebuje navrat do stabilneho domaceho prostredia', '2026-09-13T00:00:00.000Z'),
  ('Elis', 'elis-hlada-novy-domov', 'DRAFT', 'FEMALE', NULL, 132, 'UNKNOWN', NULL, 'foxteriér', 0, 0, 'Trnavský kraj', 'Trnava', 'Trnava', 'help-org:pomoc-zdruzenie-na-ochranu-zvierat-trnava', 'Združenie na ochranu zvierat Trnava', 'pomoc-zdruzenie-na-ochranu-zvierat-trnava', NULL, 'Tichá a nenáročná staršia foxteriérka, ktorá po zdravotnom zanedbaní potrebuje pokojný domov na ďalšie roky.', 'Elis je približne jedenásťročná foxteriérka. Bola nájdená po dlhšom zanedbaní a prekonala vážny zápal maternice, ktorý si vyžiadal operáciu. Útulok ju opisuje ako tichú a nenáročnú fenku a dúfa, že nájde pokojný domov. V aktuálnom profile je uvedená ako kastrovaná a očkovaná.', 0, 'https://www.trnava.utulok.sk/psy/elis', 'inga.novakova@centrum.sk', '0903 450 832', 'https://www.trnava.utulok.sk/psy/elis', 'elis foxterier trnavsky kraj trnava trnava zdruzenie na ochranu zvierat trnava ticha a nenarocna starsia foxterierka ktora po zdravotnom zanedbani potrebuje pokojny domov na dalsie roky', '2026-09-13T00:00:00.000Z'),
  ('Lio', 'lio-hlada-novy-domov', 'DRAFT', 'MALE', NULL, 4, 'MEDIUM', NULL, 'kríženec', 0, 1, 'Trnavský kraj', 'Trnava', 'Trnava', 'help-org:pomoc-zdruzenie-na-ochranu-zvierat-trnava', 'Združenie na ochranu zvierat Trnava', 'pomoc-zdruzenie-na-ochranu-zvierat-trnava', NULL, 'Typické mladé šteniatko plné energie, ktoré potrebuje čas, hranice, hygienický tréning a veľa trpezlivosti.', 'Lio je približne štvormesačný kríženec, ktorého priviezla mestská polícia. Útulok ho opisuje ako typické živé šteňa, ktoré sa ešte musí naučiť hygienu aj pravidlá fungovania v domácnosti. V dospelosti má byť pravdepodobne stredného vzrastu a je vhodný k odrastenejším deťom. Adopcia je podľa profilu možná iba do bytu alebo domu s celoročným prístupom dovnútra.', 0, 'https://www.trnava.utulok.sk/psy/lio', 'inga.novakova@centrum.sk', '0903 450 832', 'https://www.trnava.utulok.sk/psy/lio', 'lio krizenec trnavsky kraj trnava trnava zdruzenie na ochranu zvierat trnava typicke mlade steniatko plne energie ktore potrebuje cas hranice hygienicky trening a vela trpezlivosti', '2026-09-13T00:00:00.000Z'),
  ('Telka', 'telka-hlada-novy-domov', 'DRAFT', 'FEMALE', NULL, 36, 'UNKNOWN', NULL, '', 1, 0, 'Banskobystrický kraj', 'Banská Bystrica', 'Poniky', 'help-org:pomoc-oz-pes-v-nudzi', 'OZ Pes v núdzi', 'pomoc-oz-pes-v-nudzi', NULL, 'Milá, poslušná a nekonfliktná fenka s hygienickými návykmi, ktorá môže fungovať aj s iným psom či mačkou.', 'Telka je približne trojročná fenka zachránená zo zlých podmienok. Organizácia ju opisuje ako vďačnú, milú, poslušnú a nekonfliktnú. Má hygienické návyky, vychádza s inými psami a podľa profilu jej neprekážajú ani mačky. Čaká na rodinu v domácom depozite v Ponikách.', 0, 'https://www.pesvnudzi.sk/psiky-v-nudzi?p=2', 'pesvnudzi@gmail.com', '0948 213 214', 'https://www.pesvnudzi.sk/psiky-v-nudzi?p=2', 'telka banskobystricky kraj banska bystrica poniky oz pes v nudzi mila poslusna a nekonfliktna fenka s hygienickymi navykmi ktora moze fungovat aj s inym psom ci mackou', '2026-09-13T00:00:00.000Z'),
  ('Milan', 'milan-hlada-novy-domov', 'DRAFT', 'MALE', NULL, 24, 'SMALL', 8, '', 1, 0, 'Banskobystrický kraj', 'Zvolen', 'Budča', 'help-org:pomoc-oz-pes-v-nudzi', 'OZ Pes v núdzi', 'pomoc-oz-pes-v-nudzi', NULL, 'Malý, nežný a mojkavý psík, ktorý veľmi vyhľadáva blízkosť človeka.', 'Milan je približne dvojročný malý pes s hmotnosťou 8 kg. Organizácia ho opisuje ako nežného, kontaktného a mojkavého spoločníka, ktorý si užíva blízkosť človeka a po vytvorení vzťahu sa na svojho človeka silno naviaže. Hľadá domov, kde bude plnohodnotným členom rodiny.', 0, 'https://www.pesvnudzi.sk/psiky-v-nudzi?p=2', 'pesvnudzi@gmail.com', '0948 213 214', 'https://www.pesvnudzi.sk/psiky-v-nudzi?p=2', 'milan banskobystricky kraj zvolen budca oz pes v nudzi maly nezny a mojkavy psik ktory velmi vyhladava blizkost cloveka', '2026-09-13T00:00:00.000Z'),
  ('Julo', 'julo-hlada-novy-domov', 'DRAFT', 'MALE', NULL, 36, 'SMALL', 4.4, '', 1, 0, 'Banskobystrický kraj', 'Zvolen', 'Budča', 'help-org:pomoc-oz-pes-v-nudzi', 'OZ Pes v núdzi', 'pomoc-oz-pes-v-nudzi', NULL, 'Malý veselý a hravý psík, ktorý rád objavuje svet a trávi čas s človekom.', 'Julo je približne trojročný psík s hmotnosťou 4,4 kg. Podľa organizácie má veselú a hravú povahu, rád objavuje okolie a teší sa zo spoločných chvíľ s človekom. Hľadá domov, kde bude milovaným spoločníkom a bude môcť naplno rozvinúť svoju spoločenskú povahu.', 0, 'https://www.pesvnudzi.sk/psiky-v-nudzi?p=2', 'pesvnudzi@gmail.com', '0948 213 214', 'https://www.pesvnudzi.sk/psiky-v-nudzi?p=2', 'julo banskobystricky kraj zvolen budca oz pes v nudzi maly vesely a hravy psik ktory rad objavuje svet a travi cas s clovekom', '2026-09-13T00:00:00.000Z'),
  ('Kiara', 'kiara-hlada-novy-domov', 'DRAFT', 'FEMALE', NULL, 96, 'MEDIUM', 21, '', 1, 0, 'Banskobystrický kraj', 'Zvolen', 'Budča', 'help-org:pomoc-oz-pes-v-nudzi', 'OZ Pes v núdzi', 'pomoc-oz-pes-v-nudzi', NULL, 'Pokojnejšia staršia fenka s chuťou na prechádzky, ktorá by sa najlepšie cítila ako jediný pes v domácnosti.', 'Kiara je približne osemročná fenka s hmotnosťou 21 kg. Organizácia ju opisuje ako fenku s dobrou povahou, ktorá má stále chuť na spoločné prechádzky, no vie si presadiť svoje. Spoločnosť iných psov veľmi nevyhľadáva a najlepšie by sa cítila ako jediný pes v domácnosti. Hľadá pokojný, milujúci domov a verného človeka.', 0, 'https://www.pesvnudzi.sk/psiky-v-nudzi?p=2', 'pesvnudzi@gmail.com', '0948 213 214', 'https://www.pesvnudzi.sk/psiky-v-nudzi?p=2', 'kiara banskobystricky kraj zvolen budca oz pes v nudzi pokojnejsia starsia fenka s chutou na prechadzky ktora by sa najlepsie citila ako jediny pes v domacnosti', '2026-09-13T00:00:00.000Z'),
  ('Odin', 'odin-hlada-novy-domov', 'DRAFT', 'MALE', NULL, 36, 'UNKNOWN', NULL, 'kríženec NO', 0, 1, 'Trnavský kraj', 'Trnava', 'Trnava', 'help-org:pomoc-zdruzenie-na-ochranu-zvierat-trnava', 'Združenie na ochranu zvierat Trnava', 'pomoc-zdruzenie-na-ochranu-zvierat-trnava', NULL, 'Aktuálne vedený v zozname Útulku Trnava ako trojročný pes na adopciu.', '', 1, 'https://www.trnava.utulok.sk/psy/odin', 'inga.novakova@centrum.sk', '0903 450 832', 'https://www.trnava.utulok.sk/psy/odin', 'odin krizenec no trnavsky kraj trnava trnava zdruzenie na ochranu zvierat trnava aktualne vedeny v zozname utulku trnava ako trojrocny pes na adopciu', '2026-09-13T00:00:00.000Z'),
  ('Beky', 'beky-hlada-novy-domov', 'DRAFT', 'FEMALE', NULL, 168, 'UNKNOWN', NULL, 'labrador', 0, 0, 'Trnavský kraj', 'Trnava', 'Trnava', 'help-org:pomoc-zdruzenie-na-ochranu-zvierat-trnava', 'Združenie na ochranu zvierat Trnava', 'pomoc-zdruzenie-na-ochranu-zvierat-trnava', NULL, 'Aktuálne vedená v zozname Útulku Trnava ako štrnásťročná labradorka na adopciu.', '', 1, 'https://www.trnava.utulok.sk/psy/beky', 'inga.novakova@centrum.sk', '0903 450 832', 'https://www.trnava.utulok.sk/psy/beky', 'beky labrador trnavsky kraj trnava trnava zdruzenie na ochranu zvierat trnava aktualne vedena v zozname utulku trnava ako strnastrocna labradorka na adopciu', '2026-09-13T00:00:00.000Z'),
  ('Zack', 'zack-hlada-novy-domov', 'DRAFT', 'MALE', NULL, 90, 'MEDIUM', 13, 'kríženec', 0, 1, 'Trnavský kraj', 'Dunajská Streda', 'Veľký Meder', 'help-org:pomoc-dog-azyl-o-z', 'DOG AZYL, o.z.', 'pomoc-dog-azyl-o-z', NULL, 'Dog Azyl ho aktuálne vedie medzi psami na adopciu; má aj živý individuálny profil s adopčným dotazníkom.', 'Zack je kríženec narodený približne v marci 2019. Dog Azyl ho opisuje ako veselého, kontaktného a láskyplného psa s typickou teriérskou energiou. Má rád prechádzky a kontakt s človekom, so psami vychádza bez problémov. Organizácia preňho hľadá rodinu, ktorá mu zabezpečí dostatok pohybu, trpezlivé vedenie a život v úzkom kontakte s rodinou.', 0, 'https://www.dogazyl.sk/na-adopciu/zack', 'info.dogazyl@gmail.com', NULL, 'https://www.dogazyl.sk/na-adopciu/zack', 'zack krizenec trnavsky kraj dunajska streda velky meder dog azyl o z dog azyl ho aktualne vedie medzi psami na adopciu ma aj zivy individualny profil s adopcnym dotaznikom', '2026-09-13T00:00:00.000Z');

DROP TABLE IF EXISTS __psipedia_adoption_staging_guard_0038;
CREATE TABLE __psipedia_adoption_staging_guard_0038 (
  ok INTEGER NOT NULL CHECK (ok = 1)
);

-- One failing condition writes 0 into the CHECK-constrained guard and aborts
-- the migration before adoption_dogs is touched. There is no skip or upsert path.
INSERT INTO __psipedia_adoption_staging_guard_0038 (ok)
SELECT CASE WHEN
  (SELECT COUNT(*) FROM __psipedia_adoption_staging_source_0038) = 36
  AND (SELECT COUNT(DISTINCT slug) FROM __psipedia_adoption_staging_source_0038) = 36
  AND (SELECT COUNT(DISTINCT organization_import_key) FROM __psipedia_adoption_staging_source_0038) = 4
  AND NOT EXISTS (SELECT 1 FROM __psipedia_adoption_staging_source_0038 WHERE status <> 'DRAFT')
  AND NOT EXISTS (SELECT 1 FROM __psipedia_adoption_staging_source_0038 WHERE slug IN ('charlie-hlada-novy-domov', 'kira-hlada-novy-domov', 'aisha-hlada-novy-domov', 'max-hlada-novy-domov'))
  AND NOT EXISTS (
    SELECT 1 FROM __psipedia_adoption_staging_source_0038 source
    WHERE EXISTS (SELECT 1 FROM adoption_dogs target WHERE target.slug = source.slug)
  )
  AND NOT EXISTS (
    SELECT 1 FROM __psipedia_adoption_staging_source_0038 source
    WHERE (SELECT COUNT(*) FROM help_cases legacy
      WHERE legacy.category = 'adopcia' AND legacy.status = 'published' AND legacy.slug = source.slug) <> 1
  )
  AND NOT EXISTS (
    SELECT 1 FROM __psipedia_adoption_staging_source_0038 source
    WHERE (SELECT COUNT(*) FROM help_organizations organization
      WHERE organization.import_key = source.organization_import_key
        AND organization.slug = source.expected_organization_slug
        AND organization.name = source.expected_organization_name) <> 1
  )
  AND (SELECT COUNT(*) FROM __psipedia_adoption_staging_source_0038 WHERE organization_import_key = 'help-org:pomoc-unia-vzajomnej-pomoci-ludi-a-psov-u-v-p') = 16
    AND (SELECT COUNT(*) FROM __psipedia_adoption_staging_source_0038 WHERE organization_import_key = 'help-org:pomoc-dog-azyl-o-z') = 9
    AND (SELECT COUNT(*) FROM __psipedia_adoption_staging_source_0038 WHERE organization_import_key = 'help-org:pomoc-zdruzenie-na-ochranu-zvierat-trnava') = 7
    AND (SELECT COUNT(*) FROM __psipedia_adoption_staging_source_0038 WHERE organization_import_key = 'help-org:pomoc-oz-pes-v-nudzi') = 4
THEN 1 ELSE 0 END;

INSERT INTO adoption_dogs (
  name, slug, status, sex, birth_date, approximate_age_months, size, weight, breed_id, breed_name, breed_mix,
  region, district, city, organization_id, organization_name, organization_slug, main_image, gallery_json,
  short_description, description, external_source_url, contact_email, contact_phone, contact_url, search_text,
  published_at, last_verified_at, created_at, updated_at, created_by, updated_by
)
SELECT
  source.name, source.slug, 'DRAFT', source.sex, source.birth_date, source.approximate_age_months, source.size, source.weight,
  NULL, CASE WHEN source.use_legacy_breed = 1 THEN legacy.breed ELSE source.breed_name END, source.breed_mix,
  source.region, source.district, source.city, organization.id, organization.name, organization.slug,
  COALESCE(legacy.image_url, source.main_image), '[]', source.short_description,
  CASE WHEN source.use_legacy_description = 1 THEN legacy.description ELSE source.description END,
  source.external_source_url, source.contact_email, source.contact_phone, source.contact_url, source.search_text,
  NULL, source.last_verified_at, legacy.created_at, legacy.updated_at,
  'adoption-staging-import:v1', 'adoption-staging-import:v1'
FROM __psipedia_adoption_staging_source_0038 source
JOIN help_cases legacy
  ON legacy.category = 'adopcia' AND legacy.status = 'published' AND legacy.slug = source.slug
JOIN help_organizations organization
  ON organization.import_key = source.organization_import_key
  AND organization.slug = source.expected_organization_slug
  AND organization.name = source.expected_organization_name;

-- Postcondition failure also rolls the migration back as one D1 migration unit.
INSERT INTO __psipedia_adoption_staging_guard_0038 (ok)
SELECT CASE WHEN
  (SELECT COUNT(*) FROM adoption_dogs target JOIN __psipedia_adoption_staging_source_0038 source ON source.slug = target.slug) = 36
  AND (SELECT COUNT(*) FROM adoption_dogs target JOIN __psipedia_adoption_staging_source_0038 source ON source.slug = target.slug
    WHERE target.status = 'DRAFT' AND target.published_at IS NULL AND target.organization_id IS NOT NULL) = 36
  AND (SELECT COUNT(DISTINCT target.organization_id) FROM adoption_dogs target
    JOIN __psipedia_adoption_staging_source_0038 source ON source.slug = target.slug) = 4
  AND NOT EXISTS (
    SELECT 1 FROM adoption_dogs target
    JOIN __psipedia_adoption_staging_source_0038 source ON source.slug = target.slug
    JOIN help_organizations organization ON organization.id = target.organization_id
    WHERE target.organization_name <> organization.name OR target.organization_slug <> organization.slug
  )
THEN 1 ELSE 0 END;

DROP TABLE __psipedia_adoption_staging_guard_0038;
DROP TABLE __psipedia_adoption_staging_source_0038;
